def choose_move(observation):
    # Defensive access to observation fields
    grid_width = observation.get('grid_width', 0)
    grid_height = observation.get('grid_height', 0)
    own_position = observation.get('player', {}).get('position', [0, 0])
    enemies = observation.get('enemies', [])
    resources = observation.get('resources', [])
    territory_control_score = observation.get('territory_control_score', 0)
    resource_positions = resources if resources is not None else []
    enemy_positions = enemies if enemies is not None else []

    # Helper functions
    def in_bounds(pos):
        return 0 <= pos[0] < grid_width and 0 <= pos[1] < grid_height

    def get_closest(targets, current):
        min_dist = float('inf')
        closest = None
        for t in targets:
            dist = abs(t[0] - current[0]) + abs(t[1] - current[1])
            if dist < min_dist:
                min_dist = dist
                closest = t
        return closest

    # Determine safe moves (not moving into enemies)
    def is_safe_move(dx, dy):
        new_pos = [own_position[0] + dx, own_position[1] + dy]
        if not in_bounds(new_pos):
            return False
        for enemy in enemy_positions:
            if enemy == new_pos:
                return False
        return True

    # Find resource to collect
    target_resource = get_closest(resource_positions, own_position)

    # Decide move
    move_x, move_y = 0, 0

    if target_resource:
        delta_x = target_resource[0] - own_position[0]
        delta_y = target_resource[1] - own_position[1]
        # Prioritize horizontal or vertical movement towards resource
        if abs(delta_x) > abs(delta_y):
            step_x = 1 if delta_x > 0 else -1
            step_y = 0
        else:
            step_x = 0
            step_y = 1 if delta_y > 0 else -1
        # Check if move is safe; if not, try alternative directions
        if is_safe_move(step_x, step_y):
            move_x, move_y = step_x, step_y
        else:
            # Try other directions to approach resource
            options = []
            if delta_x != 0:
                options.append((1 if delta_x > 0 else -1, 0))
            if delta_y != 0:
                options.append((0, 1 if delta_y > 0 else -1))
            for dx_alt, dy_alt in options:
                if is_safe_move(dx_alt, dy_alt):
                    move_x, move_y = dx_alt, dy_alt
                    break
    else:
        # No resources detected, explore or evade
        # Simple heuristic: move away from closest enemy if any
        closest_enemy = get_closest(enemy_positions, own_position)
        if closest_enemy:
            delta_x = own_position[0] - closest_enemy[0]
            delta_y = own_position[1] - closest_enemy[1]
            if abs(delta_x) > abs(delta_y):
                move_x = 1 if delta_x >= 0 else -1
                move_y = 0
            else:
                move_x = 0
                move_y = 1 if delta_y >= 0 else -1
            if not is_safe_move(move_x, move_y):
                # Try to move in other directions to escape
                for dx_opt in [-1, 0, 1]:
                    for dy_opt in [-1, 0, 1]:
                        if abs(dx_opt) + abs(dy_opt) == 1:
                            if is_safe_move(dx_opt, dy_opt):
